import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    adj = [[] for _ in range(n)]
    for u, v, minutes, energy in roads:
        adj[u].append((v, minutes, energy))

    is_station = [False] * n
    for x in stations:
        is_station[x] = True

    C, K = capacity, max_swaps
    INF = float("inf")

    # dist[u][charge][k] = earliest minutes to stand at u with `charge` battery
    # having used exactly k swaps. Lexicographic cost of the state = (minutes, k).
    dist = [[[INF] * (K + 1) for _ in range(C + 1)] for _ in range(n)]
    dist[s][C][0] = 0

    heap = [(0, 0, s, C)]            # (minutes, swaps_used, junction, charge)
    while heap:
        minutes, k, u, ch = heapq.heappop(heap)
        if minutes > dist[u][ch][k]:
            continue                 # stale heap entry
        if u == t:                   # first settled state at t is optimal
            return (minutes, k)

        # drive a road
        for v, m, e in adj[u]:
            if ch >= e:              # enough charge (always true when e <= 0)
                nc = ch - e
                if nc > C:           # regeneration beyond capacity is lost
                    nc = C
                nm = minutes + m
                if nm < dist[v][nc][k]:
                    dist[v][nc][k] = nm
                    heapq.heappush(heap, (nm, k, v, nc))

        # swap the battery (skipping full-battery swaps is safe, see above)
        if k < K and ch < C and is_station[u]:
            nm = minutes + swap_time
            if nm < dist[u][C][k + 1]:
                dist[u][C][k + 1] = nm
                heapq.heappush(heap, (nm, k + 1, u, C))

    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    B = budget
    G = min(max_gap, n)          # a dropped run never exceeds n
    B1 = B + 1
    NEG = -10**15                # unreachable sentinel (|score| <= ~2.4e8)

    # dp[g][b]: best score with kept-length b and trailing dropped run g
    dp = [[NEG] * B1 for _ in range(G + 1)]
    l0, v0, p0 = messages[0]
    if l0 <= B:
        dp[0][l0] = v0           # keep message 0 (no bonus: no previous message)
    if not p0 and G >= 1:
        dp[1][0] = 0             # drop message 0

    cum = l0                     # sum of lengths processed so far
    for i in range(1, n):
        l, v, p = messages[i]
        prev_hi = min(cum, B)    # max reachable b before this message
        cum += l
        keep_hi = min(prev_hi, B - l)   # max b allowing a keep (<0 => cannot keep)
        g_hi = min(i, G)         # max reachable trailing run after i messages

        new = [[NEG] * B1 for _ in range(G + 1)]
        new0 = new[0]            # keeping message i resets the dropped run to 0

        for g in range(g_hi + 1):
            row = dp[g]
            add = (v + bonus) if g == 0 else v   # g==0 <=> message i-1 was kept
            drow = new[g + 1] if g < G else None
            if p:
                # pinned: keeping is forced
                for b in range(keep_hi + 1):
                    s = row[b]
                    if s != NEG:
                        c = s + add
                        if c > new0[b + l]:
                            new0[b + l] = c
            else:
                for b in range(prev_hi + 1):
                    s = row[b]
                    if s != NEG:
                        # drop message i (dropped run grows by one)
                        if drow is not None and s > drow[b]:
                            drow[b] = s
                        # keep message i
                        if b <= keep_hi:
                            c = s + add
                            if c > new0[b + l]:
                                new0[b + l] = c
        dp = new

    best = NEG
    for row in dp:
        for s in row:
            if s > best:
                best = s
    return None if best == NEG else best

import re

_NAME_RE = re.compile(r"[a-z0-9_]+")      # principal / user / group NAME
_WORD_RE = re.compile(r"[a-z]+")          # action word
_SEG_RE = re.compile(r"[a-z0-9._-]+")     # literal resource/path segment


def _rule_resource_segments(text):
    """Rule RESOURCE -> list of segments, or None if invalid."""
    if text == "/":
        return []
    if not text.startswith("/"):
        return None
    segs = text[1:].split("/")
    for seg in segs:
        if seg == "*" or seg == "**":
            continue
        if _SEG_RE.fullmatch(seg) is None:
            return None
    return segs


def _request_path_segments(text):
    """Request path -> list of segments, or None if invalid (no wildcards)."""
    if text == "/":
        return []
    if not text.startswith("/"):
        return None
    segs = text[1:].split("/")
    for seg in segs:
        if _SEG_RE.fullmatch(seg) is None:
            return None
    return segs


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    # ---- validate and compile all rules (before any request is touched) ----
    compiled = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields

        if effect != "ALLOW" and effect != "DENY":
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            pkind, pval, pspec = 0, None, 0
        elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]):
            pkind, pval, pspec = 1, principal[5:], 2
        elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]):
            pkind, pval, pspec = 2, principal[6:], 1
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            action_set, aspec = None, 0
        else:
            words = action.split(",")
            for w in words:
                if _WORD_RE.fullmatch(w) is None:
                    raise ValueError(f"rule {i}: bad action {action!r}")
            action_set, aspec = frozenset(words), 1

        rsegs = _rule_resource_segments(resource)
        if rsegs is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        # Compile the resource pattern (consecutive "**" collapse into one):
        #   kind 0: no wildcards           -> exact tuple comparison
        #   kind 1: only "*"               -> length + literal-run comparison
        #   kind 2: only "**" segments     -> matches every path
        #   kind 3: general glob with "**" -> bit-parallel DP (no backtracking)
        collapsed = []
        has_star = has_glob = False
        lcount = 0
        for seg in rsegs:
            if seg == "**":
                has_glob = True
                if collapsed and collapsed[-1] == "**":
                    continue
            elif seg == "*":
                has_star = True
            else:
                lcount += 1
            collapsed.append(seg)

        if not has_glob and not has_star:
            mkind, mdata = 0, tuple(rsegs)
        elif not has_glob:
            runs = []
            k = 0
            while k < len(rsegs):
                if rsegs[k] == "*":
                    k += 1
                else:
                    s = k
                    while k < len(rsegs) and rsegs[k] != "*":
                        k += 1
                    runs.append((s, k, tuple(rsegs[s:k])))
            mkind, mdata = 1, (len(rsegs), tuple(runs))
        elif all(seg == "**" for seg in collapsed):
            mkind, mdata = 2, None
        else:
            ops = []
            min_len = 0
            for seg in collapsed:
                if seg == "**":
                    ops.append((2, None))
                elif seg == "*":
                    ops.append((1, None))
                    min_len += 1
                else:
                    ops.append((0, seg))
                    min_len += 1
            mkind, mdata = 3, (tuple(ops), min_len)

        compiled.append((effect, pkind, pval, action_set, mkind, mdata, i,
                         lcount, pspec, aspec))

    # ---- validate and prepare all requests ----
    nreq = len(requests)
    req_action = [None] * nreq
    req_segs = [None] * nreq
    req_n = [0] * nreq
    req_masks = [None] * nreq      # segment value -> bitmask of its 1-based positions
    req_full = [0] * nreq          # bits 1..n set
    req_shifts = [None] * nreq     # shift amounts for the "**" prefix-or
    by_user = {}
    by_group = {}

    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req

        if not isinstance(user, str) or _NAME_RE.fullmatch(user) is None:
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list):
            raise ValueError(f"request {j}: bad groups")
        for g in groups:
            if not isinstance(g, str) or _NAME_RE.fullmatch(g) is None:
                raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or _WORD_RE.fullmatch(action) is None:
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str):
            raise ValueError(f"request {j}: bad path {path!r}")
        psegs = _request_path_segments(path)
        if psegs is None:
            raise ValueError(f"request {j}: bad path {path!r}")

        segt = tuple(psegs)
        n = len(segt)
        masks = {}
        bit = 2
        for seg in segt:
            masks[seg] = masks.get(seg, 0) | bit
            bit <<= 1

        req_action[j] = action
        req_segs[j] = segt
        req_n[j] = n
        req_masks[j] = masks
        req_full[j] = (1 << (n + 1)) - 2
        req_shifts[j] = tuple(1 << t for t in range(n.bit_length()))

        by_user.setdefault(user, []).append(j)
        for g in set(groups):
            by_group.setdefault(g, []).append(j)

    # ---- evaluate ----
    # Process rules most-specific first; ties broken by DENY-before-ALLOW and
    # then by lowest index.  The first processed rule that matches a request
    # is therefore exactly the rule the spec says decides that request.
    order = sorted(
        range(len(compiled)),
        key=lambda r: (-compiled[r][7], -compiled[r][8], -compiled[r][9],
                       0 if compiled[r][0] == "DENY" else 1, r))

    results = [None] * nreq
    decided = [False] * nreq
    remaining = nreq
    all_idx = list(range(nreq))

    for r in order:
        if remaining == 0:
            break
        effect, pkind, pval, action_set, mkind, mdata, idx, _, _, _ = compiled[r]

        if pkind == 0:
            cand = all_idx
        elif pkind == 1:
            cand = by_user.get(pval)
        else:
            cand = by_group.get(pval)
        if not cand:
            continue

        msg = f"{effect} by rule {idx}"

        if mkind == 2:                       # resource matches any path
            for j in cand:
                if decided[j] or (action_set is not None
                                  and req_action[j] not in action_set):
                    continue
                results[j] = msg
                decided[j] = True
                remaining -= 1
        elif mkind == 0:                     # exact literal path
            pat = mdata
            for j in cand:
                if decided[j] or (action_set is not None
                                  and req_action[j] not in action_set):
                    continue
                if req_segs[j] == pat:
                    results[j] = msg
                    decided[j] = True
                    remaining -= 1
        elif mkind == 1:                     # only single-segment "*" wildcards
            m, runs = mdata
            for j in cand:
                if decided[j] or (action_set is not None
                                  and req_action[j] not in action_set):
                    continue
                segs = req_segs[j]
                if len(segs) != m:
                    continue
                ok = True
                for s, e, t in runs:
                    if segs[s:e] != t:
                        ok = False
                        break
                if ok:
                    results[j] = msg
                    decided[j] = True
                    remaining -= 1
        else:                                # general glob containing "**"
            ops, min_len = mdata
            for j in cand:
                if decided[j] or (action_set is not None
                                  and req_action[j] not in action_set):
                    continue
                n = req_n[j]
                if n < min_len:
                    continue
                mget = req_masks[j].get
                full = req_full[j]
                shifts = req_shifts[j]
                # Bit j of `row` <=> the processed pattern prefix matches the
                # path prefix of length j.  Each step is O(1) bigint ops, so
                # matching is polynomial even with many "**" segments.
                row = 1
                for op, v in ops:
                    if op == 0:                    # literal segment
                        row = (row << 1) & mget(v, 0)
                    elif op == 1:                  # "*" : exactly one segment
                        row = (row << 1) & full
                    else:                          # "**": prefix-or of row
                        for s in shifts:
                            row |= row << s
                    if not row:
                        break
                if (row >> n) & 1:
                    results[j] = msg
                    decided[j] = True
                    remaining -= 1

    return [res if res is not None else "DENY by default" for res in results]

