import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type_name(v):
    if v is None:
        return "null"
    if isinstance(v, bool):      # before int: bool is a subclass of int
        return "bool"
    if isinstance(v, dict):
        return "dict"
    if isinstance(v, list):
        return "list"
    if isinstance(v, str):
        return "str"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    return type(v).__name__


def _child_path(parent, name):
    if _IDENT_RE.fullmatch(name):
        return parent + "." + name
    return parent + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _merge_into(T, O, P, L, warnings):
    """Merge overlay dict O into target dict T at path P (layer index L)."""
    for K, V in O.items():
        if not isinstance(K, str):
            raise TypeError(f"layer {L}: non-string key at {P}")

        if K.startswith("-"):            # "-" wins even if K also ends with "+"
            directive, NAME = "delete", K[1:]
        elif K.endswith("+"):
            directive, NAME = "append", K[:-1]
        else:
            directive, NAME = "set", K

        if NAME == "":
            raise ValueError(f"layer {L}: empty key name at {P}")

        Q = _child_path(P, NAME)

        if directive == "delete":
            if V is not None:
                raise ValueError(f"layer {L}: delete directive needs null at {Q}")
            if NAME in T:
                del T[NAME]
            else:
                warnings.append(f"layer {L}: delete of missing key at {Q}")

        elif directive == "append":
            if not isinstance(V, list):
                raise ValueError(f"layer {L}: append directive needs a list at {Q}")
            if NAME not in T:
                T[NAME] = copy.deepcopy(V)
            elif isinstance(T[NAME], list):
                T[NAME].extend(copy.deepcopy(V))
            else:
                raise ValueError(
                    f"layer {L}: cannot append to {_type_name(T[NAME])} at {Q}"
                )

        else:  # plain set
            if NAME in T:
                old, new = _type_name(T[NAME]), _type_name(V)
                if old != new:
                    warnings.append(f"layer {L}: type change at {Q}: {old} -> {new}")
            if isinstance(V, dict):
                if NAME not in T or not isinstance(T[NAME], dict):
                    T[NAME] = {}          # new key goes at end; existing keeps position
                _merge_into(T[NAME], V, Q, L, warnings)
            else:
                T[NAME] = copy.deepcopy(V)   # lists (and their contents) are opaque


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")
    result = {}
    warnings = []
    for L, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {L} is not a dict")
        _merge_into(result, layer, "$", L, warnings)
    return result, warnings

import re

_PART = r"(?:0|[1-9][0-9]*)"
_VERSION_RE = re.compile(
    rf"({_PART})\.({_PART})\.({_PART})(?:~rc([1-9][0-9]*))?"
)
_WILDCARD_RE = re.compile(rf"({_PART})(?:\.({_PART}))?\.\*")
_AT_RE = re.compile(rf"@({_PART})\.({_PART})")


def _number_key(text: str) -> tuple[int, str]:
    # Canonical decimal strings compare numerically by length, then lexicographically.
    return (len(text), text)


def _parse_version(text: str):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        return None

    major, minor, patch, rc = match.groups()
    return (
        _number_key(major),
        _number_key(minor),
        _number_key(patch),
        None if rc is None else _number_key(rc),
    )


def _version_key(version):
    major, minor, patch, rc = version
    return (
        major,
        minor,
        patch,
        0 if rc is not None else 1,  # release candidates sort before releases
        (0, "") if rc is None else rc,
    )


def _parse_clause(clause: str):
    if clause == "*":
        return ("any",)

    for prefix, kind in (
        ("!=", "ne"),
        (">=", "ge"),
        ("<=", "le"),
        ("=", "eq"),
        (">", "gt"),
        ("<", "lt"),
    ):
        if clause.startswith(prefix):
            version = _parse_version(clause[len(prefix):])
            if version is None:
                return None
            return (kind, _version_key(version))

    match = _WILDCARD_RE.fullmatch(clause)
    if match is not None:
        major, minor = match.groups()
        return (
            "wildcard",
            _number_key(major),
            None if minor is None else _number_key(minor),
        )

    match = _AT_RE.fullmatch(clause)
    if match is not None:
        return ("at", _number_key(match.group(1)), _number_key(match.group(2)))

    version = _parse_version(clause)
    if version is None:
        return None
    return ("eq", _version_key(version))


def _parse_constraint(constraint: str):
    alternatives = []

    for alternative_number, raw_alternative in enumerate(
        constraint.split("|"), start=1
    ):
        alternative = raw_alternative.strip(" ")
        allows_rc = False

        if alternative.startswith("?"):
            allows_rc = True
            alternative = alternative[1:].strip(" ")

        if alternative == "":
            raise ValueError(f"alternative {alternative_number} is empty")

        clauses = []
        for clause_number, raw_clause in enumerate(
            alternative.split(","), start=1
        ):
            clause = raw_clause.strip(" ")
            parsed_clause = _parse_clause(clause)
            if parsed_clause is None:
                raise ValueError(
                    f"alternative {alternative_number}, clause {clause_number}: "
                    f"invalid clause {clause!r}"
                )
            clauses.append(parsed_clause)

        alternatives.append((allows_rc, clauses))

    return alternatives


def _clause_matches(clause, version, version_key) -> bool:
    kind = clause[0]

    if kind == "any":
        return True

    if kind == "wildcard":
        _, major, minor = clause
        return version[0] == major and (
            minor is None or version[1] == minor
        )

    if kind == "at":
        return version[0] == clause[1] and version[1] >= clause[2]

    if kind == "eq":
        return version_key == clause[1]
    if kind == "ne":
        return version_key != clause[1]
    if kind == "gt":
        return version_key > clause[1]
    if kind == "ge":
        return version_key >= clause[1]
    if kind == "lt":
        return version_key < clause[1]
    if kind == "le":
        return version_key <= clause[1]

    raise AssertionError(f"unknown clause kind: {kind}")


def _alternative_matches(alternative, version, version_key) -> bool:
    allows_rc, clauses = alternative

    if version[3] is not None and not allows_rc:
        return False

    return all(
        _clause_matches(clause, version, version_key)
        for clause in clauses
    )


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    versions = []
    for index, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {index}: {element!r}")

        version = _parse_version(element)
        if version is None:
            raise ValueError(f"invalid version at index {index}: {element!r}")

        versions.append(version)

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = _parse_constraint(constraint)

    best_element = None
    best_key = None

    for element, version in zip(available, versions):
        key = _version_key(version)
        if any(
            _alternative_matches(alternative, version, key)
            for alternative in alternatives
        ):
            if best_key is None or key > best_key:
                best_element = element
                best_key = key

    return best_element

import sys

# CPython 3.11+ caps int<->str conversions at 4300 digits. A Sieve query may
# be up to 100k characters, so an INT literal can have more digits than that;
# lift the cap (_atoi below also has a manual fallback just in case).
try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass

_KEYWORDS = {"and": "AND", "or": "OR", "not": "NOT", "in": "IN", "has": "HAS"}
_CMP_INDEX = {"=": 0, "!=": 1, "<": 2, "<=": 3, ">": 4, ">=": 5}
_PRECEDENCE = {"LP": 0, "OR": 1, "AND": 2, "NOT": 3}
_RPN_OPCODE = {"NOT": 3, "AND": 4, "OR": 5}

# The parser emits RPN instructions, evaluated on a stack with the tri-state
# encoded as FALSE=0, UNKNOWN=1, TRUE=2:
#   (0, field, cmp_index, literal)    FIELD cmp_op literal
#   (1, field, frozenset(literals))   FIELD in [ ... ]
#   (2, field)                        has FIELD
#   (3,) not   (4,) and   (5,) or

_CHUNK = 1000
_CHUNK_MULT = 10 ** _CHUNK


def _atoi(raw):
    try:
        return int(raw)
    except ValueError:  # digit cap still active: parse in 1000-digit chunks
        neg = raw[0] == "-"
        s = raw[1:] if neg else raw
        first = len(s) % _CHUNK
        n = int(s[:first]) if first else 0
        for k in range(first, len(s), _CHUNK):
            n = n * _CHUNK_MULT + int(s[k:k + _CHUNK])
        return -n if neg else n


def _tokenize(query):
    """Tokenize the whole query left to right. Return (tokens, None) or
    (None, error_tuple). Each token is (kind, value, pos, raw_source_text)."""
    tokens = []
    append = tokens.append
    i = 0
    n = len(query)
    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
        elif c == "(":
            append(("LP", None, i, "(")); i += 1
        elif c == ")":
            append(("RP", None, i, ")")); i += 1
        elif c == "[":
            append(("LB", None, i, "[")); i += 1
        elif c == "]":
            append(("RB", None, i, "]")); i += 1
        elif c == ",":
            append(("COMMA", None, i, ",")); i += 1
        elif c == "=":
            append(("CMP", "=", i, "=")); i += 1
        elif c == "!":
            if query.startswith("!=", i):
                append(("CMP", "!=", i, "!=")); i += 2
            else:
                return None, ("error", i, "unexpected character '!'")
        elif c == "<":
            if query.startswith("<=", i):
                append(("CMP", "<=", i, "<=")); i += 2
            else:
                append(("CMP", "<", i, "<")); i += 1
        elif c == ">":
            if query.startswith(">=", i):
                append(("CMP", ">=", i, ">=")); i += 2
            else:
                append(("CMP", ">", i, ">")); i += 1
        elif c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    return None, ("error", i, "unterminated string")
                ch = query[j]
                if ch == '"':
                    break
                if ch == "\\":
                    nxt = query[j + 1] if j + 1 < n else ""
                    if nxt == '"':
                        buf.append('"'); j += 2
                    elif nxt == "\\":
                        buf.append("\\"); j += 2
                    else:
                        return None, ("error", j, "bad escape")
                else:
                    buf.append(ch)
                    j += 1
            append(("STR", "".join(buf), i, query[i:j + 1]))
            i = j + 1
        elif "0" <= c <= "9":
            j = i + 1
            while j < n and "0" <= query[j] <= "9":
                j += 1
            raw = query[i:j]
            append(("INT", _atoi(raw), i, raw))
            i = j
        elif c == "-":
            if i + 1 < n and "0" <= query[i + 1] <= "9":
                j = i + 1
                while j < n and "0" <= query[j] <= "9":
                    j += 1
                raw = query[i:j]
                append(("INT", _atoi(raw), i, raw))
                i = j
            else:
                return None, ("error", i, "unexpected character '-'")
        elif ("a" <= c <= "z") or ("A" <= c <= "Z") or c == "_":
            j = i + 1
            while j < n:
                cj = query[j]
                if (("a" <= cj <= "z") or ("A" <= cj <= "Z")
                        or ("0" <= cj <= "9") or cj == "_" or cj == "."):
                    j += 1
                else:
                    break
            word = query[i:j]
            kind = _KEYWORDS.get(word)
            if kind is None:
                append(("FIELD", word, i, word))
            else:
                append((kind, None, i, word))
            i = j
        else:
            return None, ("error", i, "unexpected character '%s'" % c)
    return tokens, None


def _err_at(tokens, idx, qlen):
    if idx < len(tokens):
        tok = tokens[idx]
        return ("error", tok[2], "unexpected token '%s'" % tok[3])
    return ("error", qlen, "unexpected end of input")


def _parse(tokens, qlen):
    """Iterative shunting-yard parse (no recursion, so 3000-deep nesting of
    parentheses / `not` chains is fine). Fails at exactly the first token
    where a recursive-descent parser for the grammar would fail.
    Return (rpn, None) or (None, error_tuple)."""
    rpn = []
    stack = []          # "LP" / "OR" / "AND" / "NOT"
    open_parens = 0
    i = 0
    t = len(tokens)
    expect_operand = True
    while True:
        kind = tokens[i][0] if i < t else "END"
        if expect_operand:
            if kind == "NOT":
                stack.append("NOT")
                i += 1
            elif kind == "LP":
                stack.append("LP")
                open_parens += 1
                i += 1
            elif kind == "HAS":
                if i + 1 < t and tokens[i + 1][0] == "FIELD":
                    rpn.append((2, tokens[i + 1][1]))
                    i += 2
                    expect_operand = False
                else:
                    return None, _err_at(tokens, i + 1, qlen)
            elif kind == "FIELD":
                nxt = tokens[i + 1][0] if i + 1 < t else "END"
                if nxt == "CMP":
                    if i + 2 < t and tokens[i + 2][0] in ("INT", "STR"):
                        rpn.append((0, tokens[i][1],
                                    _CMP_INDEX[tokens[i + 1][1]],
                                    tokens[i + 2][1]))
                        i += 3
                        expect_operand = False
                    else:
                        return None, _err_at(tokens, i + 2, qlen)
                elif nxt == "IN":
                    j = i + 2
                    if j >= t or tokens[j][0] != "LB":
                        return None, _err_at(tokens, j, qlen)
                    j += 1
                    if j >= t or tokens[j][0] not in ("INT", "STR"):
                        return None, _err_at(tokens, j, qlen)
                    values = [tokens[j][1]]
                    j += 1
                    while True:
                        if j < t and tokens[j][0] == "COMMA":
                            j += 1
                            if j < t and tokens[j][0] in ("INT", "STR"):
                                values.append(tokens[j][1])
                                j += 1
                            else:
                                return None, _err_at(tokens, j, qlen)
                        elif j < t and tokens[j][0] == "RB":
                            j += 1
                            break
                        else:
                            return None, _err_at(tokens, j, qlen)
                    rpn.append((1, tokens[i][1], frozenset(values)))
                    i = j
                    expect_operand = False
                else:
                    return None, _err_at(tokens, i + 1, qlen)
            else:
                return None, _err_at(tokens, i, qlen)
        else:
            if kind == "AND" or kind == "OR":
                p = 2 if kind == "AND" else 1
                while stack and _PRECEDENCE[stack[-1]] >= p:
                    rpn.append((_RPN_OPCODE[stack.pop()],))
                stack.append(kind)
                i += 1
                expect_operand = True
            elif kind == "RP":
                if open_parens == 0:
                    return None, ("error", tokens[i][2], "unexpected token ')'")
                while stack[-1] != "LP":
                    rpn.append((_RPN_OPCODE[stack.pop()],))
                stack.pop()
                open_parens -= 1
                i += 1
            elif kind == "END":
                if open_parens:
                    return None, ("error", qlen, "unexpected end of input")
                while stack:
                    rpn.append((_RPN_OPCODE[stack.pop()],))
                break
            else:
                return None, _err_at(tokens, i, qlen)
    return rpn, None


def filter_records(query: str, records: list[dict]) -> tuple:
    tokens, err = _tokenize(query)      # lex the whole query first
    if err is not None:
        return err
    rpn, err = _parse(tokens, len(query))
    if err is not None:
        return err

    missing = object()
    selected = []
    add = selected.append
    for idx, rec in enumerate(records):
        st = []
        push = st.append
        pop = st.pop
        get = rec.get
        for ins in rpn:
            op = ins[0]
            if op == 0:                       # FIELD cmp_op literal
                v = get(ins[1], missing)
                if v is missing:
                    push(1)
                else:
                    lit = ins[3]
                    o = ins[2]
                    if type(v) is not type(lit):
                        push(0 if o == 0 else 2 if o == 1 else 1)
                    elif o == 0:
                        push(2 if v == lit else 0)
                    elif o == 1:
                        push(2 if v != lit else 0)
                    elif o == 2:
                        push(2 if v < lit else 0)
                    elif o == 3:
                        push(2 if v <= lit else 0)
                    elif o == 4:
                        push(2 if v > lit else 0)
                    else:
                        push(2 if v >= lit else 0)
            elif op == 1:                     # FIELD in [ ... ]
                v = get(ins[1], missing)
                if v is missing:
                    push(1)
                # int and str are never == in Python, so plain membership
                # already implements "equals some li of the same type".
                elif v in ins[2]:
                    push(2)
                else:
                    push(0)
            elif op == 2:                     # has FIELD
                push(2 if ins[1] in rec else 0)
            elif op == 3:                     # not
                st[-1] = 2 - st[-1]
            elif op == 4:                     # and
                b = pop()
                a = pop()
                push(a if a < b else b)
            else:                             # or
                b = pop()
                a = pop()
                push(a if a > b else b)
        if st[-1] == 2:                       # select only when TRUE
            add(idx)
    return ("ok", selected)

import sys

# Precedence (higher binds tighter).  Ternary is handled separately (lowest).
_PREC = {
    '<': 2, '<=': 2, '>': 2, '>=': 2, '==': 2, '!=': 2,  # non-associative
    '+': 3, '-': 3,                                       # left-associative
    '*': 4, '/': 4, '%': 4,                               # left-associative
    'neg': 5,    # prefix '-': looser than '^', tighter than '*'
    '^': 6,                                               # right-associative
}
_CMP_OPS = frozenset(('<', '<=', '>', '>=', '==', '!='))


def _tokenize(src):
    """Yield (kind, text, pos); kind is 'int', 'name', 'op', 'bad' or 'end'."""
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c == ' ':
            i += 1
        elif '0' <= c <= '9':
            j = i + 1
            while j < n and '0' <= src[j] <= '9':
                j += 1
            yield ('int', src[i:j], i)
            i = j
        elif 'a' <= c <= 'z' or c == '_':
            j = i + 1
            while j < n:
                d = src[j]
                if 'a' <= d <= 'z' or '0' <= d <= '9' or d == '_':
                    j += 1
                else:
                    break
            yield ('name', src[i:j], i)
            i = j
        elif c == '<' or c == '>' or c == '=' or c == '!':
            if i + 1 < n and src[i + 1] == '=':
                yield ('op', c + '=', i)          # <=  >=  ==  !=
                i += 2
            elif c == '<' or c == '>':
                yield ('op', c, i)
                i += 1
            else:                                 # bare '=' or '!'
                yield ('bad', c, i)
                i += 1
        elif c in '+-*/%^()?:':
            yield ('op', c, i)
            i += 1
        else:
            yield ('bad', c, i)
            i += 1
    yield ('end', '', n)


def _emit(code, entry):
    if entry[1] == 'neg':
        code.append(('neg',))
    else:
        code.append(('bin', entry[1], entry[2]))


def _parse(src):
    """Iterative shunting-yard parser -> flat bytecode.

    Returns (code, None) or (None, (pos, message)) for the FIRST token at
    which no valid `expr` can continue (same place recursive descent fails).

    code instructions:
      ('push', digits) ('load', pos, name) ('neg',)
      ('bin', op, pos) ('jz', target) ('jmp', target)
    """
    code = []
    ops = []  # ('op',text,pos) | ('(',) | ('?',jz_idx) | (':',jmp_idx)
    expect_operand = True
    prec = _PREC
    for kind, text, pos in _tokenize(src):
        if kind == 'bad':
            return None, (pos, "unexpected character '%s'" % text)
        if kind == 'end':
            if expect_operand:
                return None, (pos, "unexpected end of input")
            while ops:
                e = ops.pop()
                if e[0] == 'op':
                    _emit(code, e)
                elif e[0] == ':':
                    code[e[1]] = ('jmp', len(code))
                else:  # unclosed '(' or '?'
                    return None, (pos, "unexpected end of input")
            return code, None
        if expect_operand:
            if kind == 'int':
                code.append(('push', text))
                expect_operand = False
            elif kind == 'name':
                code.append(('load', pos, text))
                expect_operand = False
            elif text == '(':
                ops.append(('(',))
            elif text == '-':
                ops.append(('op', 'neg', pos))
            else:
                return None, (pos, "unexpected token '%s'" % text)
        else:
            if kind != 'op':
                return None, (pos, "unexpected token '%s'" % text)
            if text == '?':
                while ops and ops[-1][0] == 'op':
                    _emit(code, ops.pop())
                ops.append(('?', len(code)))
                code.append(('jz', 0))            # patched at ':'
                expect_operand = True
            elif text == ':':
                while ops and ops[-1][0] == 'op':
                    _emit(code, ops.pop())
                while ops and ops[-1][0] == ':':  # close inner ternaries
                    code[ops.pop()[1]] = ('jmp', len(code))
                if not ops or ops[-1][0] != '?':
                    return None, (pos, "unexpected token ':'")
                jz = ops.pop()[1]
                ops.append((':', len(code)))
                code.append(('jmp', 0))           # patched at ternary end
                code[jz] = ('jz', len(code))
                expect_operand = True
            elif text == ')':
                while True:
                    if not ops:
                        return None, (pos, "unexpected token ')'")
                    e = ops[-1]
                    if e[0] == 'op':
                        _emit(code, ops.pop())
                    elif e[0] == ':':
                        ops.pop()
                        code[e[1]] = ('jmp', len(code))
                    elif e[0] == '?':
                        return None, (pos, "unexpected token ')'")
                    else:  # '('
                        ops.pop()
                        break
                expect_operand = False
            elif text == '(':
                return None, (pos, "unexpected token '('")
            elif text == '^':
                ops.append(('op', '^', pos))      # right-assoc, top prec
                expect_operand = True
            elif text in _CMP_OPS:
                while ops and ops[-1][0] == 'op' and prec[ops[-1][1]] > 2:
                    _emit(code, ops.pop())
                if ops and ops[-1][0] == 'op':
                    # comparison already pending -> non-associative error
                    return None, (pos, "unexpected token '%s'" % text)
                ops.append(('op', text, pos))
                expect_operand = True
            else:  # '+', '-', '*', '/', '%'  (left-associative)
                p = prec[text]
                while ops and ops[-1][0] == 'op' and prec[ops[-1][1]] >= p:
                    _emit(code, ops.pop())
                ops.append(('op', text, pos))
                expect_operand = True
    # unreachable: the 'end' token always terminates the loop


def _execute(code, env):
    stack = []
    pc = 0
    n = len(code)
    while pc < n:
        ins = code[pc]
        t = ins[0]
        if t == 'push':
            stack.append(int(ins[1]))
        elif t == 'load':
            name = ins[2]
            if name in env:
                stack.append(env[name])
            else:
                return ("error", ins[1], "unknown name '%s'" % name)
        elif t == 'neg':
            stack.append(-stack.pop())
        elif t == 'jz':
            if stack.pop() == 0:
                pc = ins[1]
                continue
        elif t == 'jmp':
            pc = ins[1]
            continue
        else:  # ('bin', op, pos)
            b = stack.pop()
            a = stack.pop()
            op = ins[1]
            if op == '+':
                r = a + b
            elif op == '-':
                r = a - b
            elif op == '*':
                r = a * b
            elif op == '/':
                if b == 0:
                    return ("error", ins[2], "division by zero")
                r = a // b
            elif op == '%':
                if b == 0:
                    return ("error", ins[2], "division by zero")
                r = a % b
            elif op == '^':
                if b < 0:
                    return ("error", ins[2], "negative exponent")
                if b > 256:
                    return ("error", ins[2], "exponent too large")
                r = a ** b
            elif op == '<':
                r = 1 if a < b else 0
            elif op == '>':
                r = 1 if a > b else 0
            elif op == '<=':
                r = 1 if a <= b else 0
            elif op == '>=':
                r = 1 if a >= b else 0
            elif op == '==':
                r = 1 if a == b else 0
            else:  # '!='
                r = 1 if a != b else 0
            stack.append(r)
        pc += 1
    return ("ok", stack[-1])


def evaluate(src: str, env: dict) -> tuple:
    try:
        sys.set_int_max_str_digits(0)   # allow huge integer literals
    except Exception:
        pass
    code, err = _parse(src)
    if err is not None:
        return ("error", err[0], err[1])
    return _execute(code, env)

import re

# [sign] mantissa [exponent]; ASCII digits only, no whitespace/underscores.
_LITERAL_RE = re.compile(
    r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?'
)


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    # ---------- validation ----------
    if not isinstance(x, str) or _LITERAL_RE.fullmatch(x) is None:
        raise ValueError(f"invalid decimal literal: {x!r}")
    if max_num < 0:
        raise ValueError("max_num must be >= 0")
    if max_den < 1:
        raise ValueError("max_den must be >= 1")

    # ---------- parse x exactly as |x| = p/q (big integers, no floats) -----
    s = x
    neg = s[0] == '-'
    if s[0] in '+-':
        s = s[1:]
    exp = 0
    for i, ch in enumerate(s):
        if ch in 'eE':
            exp = int(s[i + 1:])          # int() accepts a leading '+'/'-'
            s = s[:i]
            break
    if '.' in s:
        ip, fp = s.split('.')
    else:
        ip, fp = s, ''
    mant = int(ip + fp)                   # grammar guarantees non-empty
    e = exp - len(fp)
    if e >= 0:
        p, q = mant * 10 ** e, 1
    else:
        p, q = mant, 10 ** (-e)

    def render(a: int, b: int) -> str:
        if a == 0:
            return "0/1"
        return f"{'-' if neg else ''}{a}/{b}"

    # ---------- trivial cases ----------
    if p == 0 or max_num == 0:
        return "0/1"

    N, D = max_num, max_den

    # ---------- batched Stern-Brocot / continued-fraction descent ----------
    # Invariants:
    #   lo_a/lo_b <= p/q <= hi_c/hi_d  and  lo_b*hi_c - lo_a*hi_d == 1
    #   (Farey neighbours, hence both already in lowest terms),
    #   0 <= lo_a <= N, 1 <= lo_b <= D, 0 <= hi_c <= N, 0 <= hi_d <= D.
    lo_a, lo_b = 0, 1
    hi_c, hi_d = 1, 0                     # 1/0 represents +infinity
    while True:
        # Largest k >= 0 with (lo_a + k*hi_c)/(lo_b + k*hi_d) within bounds
        # and still <= x:
        k = (N - lo_a) // hi_c
        if hi_d:
            k = min(k, (D - lo_b) // hi_d)
        # (lo_a + k hi_c) q <= (lo_b + k hi_d) p
        #   <=>  k (hi_c q - hi_d p) <= lo_b p - lo_a q
        k = min(k, (lo_b * p - lo_a * q) // (hi_c * q - hi_d * p))
        if k:
            lo_a += k * hi_c
            lo_b += k * hi_d
            if lo_a * q == lo_b * p:      # x hit exactly
                return render(lo_a, lo_b)

        # Largest k >= 0 with (k*lo_a + hi_c)/(k*lo_b + hi_d) within bounds
        # and still >= x:
        k2 = (D - hi_d) // lo_b
        if lo_a:
            k2 = min(k2, (N - hi_c) // lo_a)
        # (k lo_a + hi_c) q >= (k lo_b + hi_d) p
        #   <=>  k (lo_b p - lo_a q) <= hi_c q - hi_d p
        k2 = min(k2, (hi_c * q - hi_d * p) // (lo_b * p - lo_a * q))
        if k2:
            hi_c += k2 * lo_a
            hi_d += k2 * lo_b
            if hi_c * q == hi_d * p:      # x hit exactly
                return render(hi_c, hi_d)

        if not k and not k2:
            break

    # Every reduced fraction strictly between lo and hi has the form
    # (s*lo_a + t*hi_c)/(s*lo_b + t*hi_d) with s,t >= 1, so its numerator and
    # denominator are at least those of the mediant — which is already out of
    # bounds (otherwise one side could still move).  Hence the answer is lo
    # or hi; anything outside [lo, hi] is strictly farther from x.
    if hi_d == 0:                         # hi is +infinity: x >= every candidate
        return render(lo_a, lo_b)

    # |x - lo| = (p lo_b - lo_a q)/(q lo_b),  |hi - x| = (hi_c q - hi_d p)/(q hi_d)
    d_lo = (p * lo_b - lo_a * q) * hi_d
    d_hi = (hi_c * q - hi_d * p) * lo_b
    if d_lo < d_hi:
        return render(lo_a, lo_b)
    if d_hi < d_lo:
        return render(hi_c, hi_d)
    # Equal distance: smaller lowest-terms denominator wins; on equal
    # denominators the smaller absolute value wins, which is lo (0 <= lo < hi).
    return render(lo_a, lo_b) if lo_b <= hi_d else render(hi_c, hi_d)

from bisect import bisect_left, bisect_right
from array import array

def run_ops(ops: list[tuple]) -> list:
    # Only "set" can ever make a key present, so these are all possible keys.
    keys = sorted({op[2] for op in ops if op[0] == "set"})
    where = {k: i for i, k in enumerate(keys)}
    m = len(keys)

    # Persistent segment tree. Node 0 is the shared empty node.
    L = array("i", [0])
    R = array("i", [0])
    C = array("i", [0])      # number of present keys in subtree
    S = array("q", [0])      # sum of values in subtree

    def upd(node: int, l: int, r: int, i: int, c: int, s: int) -> int:
        if l == r:
            L.append(0); R.append(0); C.append(c); S.append(s)
            return len(C) - 1
        mid = (l + r) >> 1
        if i <= mid:
            nl = upd(L[node], l, mid, i, c, s)
            nr = R[node]
        else:
            nl = L[node]
            nr = upd(R[node], mid + 1, r, i, c, s)
        L.append(nl); R.append(nr)
        C.append(C[nl] + C[nr])
        S.append(S[nl] + S[nr])
        return len(C) - 1

    def point(node: int, i: int) -> tuple[int, int]:
        l, r = 0, m - 1
        while node:
            if l == r:
                return C[node], S[node]
            mid = (l + r) >> 1
            if i <= mid:
                node = L[node]; r = mid
            else:
                node = R[node]; l = mid + 1
        return 0, 0

    def pref(node: int, p: int) -> tuple[int, int]:
        # count/sum over compressed positions <= p
        c = s = 0
        l, r = 0, m - 1
        while node and p >= l:
            if r <= p:
                c += C[node]; s += S[node]
                break
            mid = (l + r) >> 1
            if p <= mid:
                node = L[node]; r = mid
            else:
                lc = L[node]
                c += C[lc]; s += S[lc]
                node = R[node]; l = mid + 1
        return c, s

    def select(node: int, k: int) -> int:
        l, r = 0, m - 1
        while l != r:
            mid = (l + r) >> 1
            lc = L[node]
            if k <= C[lc]:
                node = lc; r = mid
            else:
                k -= C[lc]
                node = R[node]; l = mid + 1
        return l

    roots = [0]   # version id -> segment-tree root; version 0 is empty
    ans = []

    for op in ops:
        typ, v = op[0], op[1]
        if v < 0 or v >= len(roots):
            ans.append("BADVER")
            continue

        root = roots[v]

        if typ == "set":
            i = where[op[2]]
            roots.append(upd(root, 0, m - 1, i, 1, op[3]))
            ans.append(len(roots) - 1)

        elif typ == "del":
            i = where.get(op[2])
            if i is None:
                ans.append("NOKEY")
            else:
                c, _ = point(root, i)
                if not c:
                    ans.append("NOKEY")
                else:
                    roots.append(upd(root, 0, m - 1, i, 0, 0))
                    ans.append(len(roots) - 1)

        elif typ == "get":
            i = where.get(op[2])
            if i is None:
                ans.append(None)
            else:
                c, s = point(root, i)
                ans.append(s if c else None)

        elif typ == "count" or typ == "sum":
            lo, hi = op[2], op[3]
            a = bisect_left(keys, lo)
            b = bisect_right(keys, hi) - 1
            if a > b:
                ans.append(0)
            else:
                c2, s2 = pref(root, b)
                c1, s1 = pref(root, a - 1)
                ans.append(c2 - c1 if typ == "count" else s2 - s1)

        else:  # "kth"
            k = op[2]
            if k < 1 or k > C[root]:
                ans.append(None)
            else:
                ans.append(keys[select(root, k)])

    return ans

from array import array

def run_ops(ops: list[tuple]) -> list:
    if not ops:
        return []

    # ---- coordinate compression (all endpoints / query points are known up front) ----
    pts = []
    for op in ops:
        k = op[0]
        if k == "book":
            pts.append(op[1]); pts.append(op[2])
        elif k == "cancel":
            pts.append(op[1])
        elif k == "first_fit":
            pts.append(op[1])
        else:                       # free_between
            pts.append(op[1]); pts.append(op[2])

    INF = 1 << 62                   # far right; x + d <= 2e9 << INF
    xs = sorted(set(pts))
    xs.append(INF)
    pos = {x: i for i, x in enumerate(xs)}
    n = len(xs) - 1                 # elementary intervals [xs[i], xs[i+1])

    N = 1
    while N < n:
        N <<= 1
    LOG = N.bit_length() - 1
    M = 2 * N

    length = array('q', [0]) * M    # total integer times in node
    free   = array('q', [0]) * M    # total free times
    pref   = array('q', [0]) * M    # longest free prefix
    suff   = array('q', [0]) * M    # longest free suffix
    best   = array('q', [0]) * M    # longest free run
    L      = array('q', [0]) * M    # left coordinate of node
    lazy   = array('b', [-1]) * M   # -1 none, 0 = all occupied, 1 = all free

    for i in range(n):
        node = N + i
        a = xs[i]; b = xs[i + 1]
        ln = b - a
        length[node] = ln; free[node] = ln
        pref[node] = ln; suff[node] = ln; best[node] = ln
        L[node] = a
    for i in range(n, N):
        L[N + i] = INF
    for node in range(N - 1, 0, -1):
        lft = node << 1; rgt = lft | 1
        ln = length[lft] + length[rgt]
        length[node] = ln; L[node] = L[lft]
        free[node] = ln; pref[node] = ln; suff[node] = ln; best[node] = ln

    def _set(i, v):
        if v:
            f = length[i]
            free[i] = f; pref[i] = f; suff[i] = f; best[i] = f
        else:
            free[i] = 0; pref[i] = 0; suff[i] = 0; best[i] = 0
        lazy[i] = v

    def _pull(i):
        lft = i << 1; rgt = lft | 1
        free[i] = free[lft] + free[rgt]
        pref[i] = length[lft] + pref[rgt] if pref[lft] == length[lft] else pref[lft]
        suff[i] = length[rgt] + suff[lft] if suff[rgt] == length[rgt] else suff[rgt]
        b1 = best[lft]; b2 = best[rgt]
        m = b1 if b1 >= b2 else b2
        cross = suff[lft] + pref[rgt]
        best[i] = m if m >= cross else cross

    def _push_path(l, r):           # l, r already offset by N; r exclusive
        for i in range(LOG, 0, -1):
            a = l >> i
            if (a << i) != l:
                v = lazy[a]
                if v != -1:
                    _set(a << 1, v); _set((a << 1) | 1, v); lazy[a] = -1
            b = r >> i
            if (b << i) != r:
                c = (r - 1) >> i
                v = lazy[c]
                if v != -1:
                    _set(c << 1, v); _set((c << 1) | 1, v); lazy[c] = -1

    def _pull_path(l, r):
        for i in range(1, LOG + 1):
            a = l >> i
            if (a << i) != l:
                _pull(a)
            b = r >> i
            if (b << i) != r:
                _pull((r - 1) >> i)

    def range_set(ql, qr, v):       # assign whole elementary range to occupied(0)/free(1)
        l = ql + N; r = qr + N
        _push_path(l, r)
        ll = l; rr = r
        while ll < rr:
            if ll & 1:
                _set(ll, v); ll += 1
            if rr & 1:
                rr -= 1; _set(rr, v)
            ll >>= 1; rr >>= 1
        _pull_path(l, r)

    def range_free(ql, qr):         # number of free integer times in [xs[ql], xs[qr])
        l = ql + N; r = qr + N
        _push_path(l, r)
        res = 0
        while l < r:
            if l & 1:
                res += free[l]; l += 1
            if r & 1:
                r -= 1; res += free[r]
            l >>= 1; r >>= 1
        return res

    def search(i, run, d):
        # Only called on a node known to contain a fit. Returns (answer, new_run).
        pf = pref[i]
        if run + pf >= d:
            return (L[i] - run, 0)
        if best[i] < d:
            return (None, run + pf) if pf == length[i] else (None, suff[i])
        lft = i << 1
        ans, run2 = search(lft, run, d)
        if ans is not None:
            return (ans, 0)
        return search(lft | 1, run2, d)

    def first_fit(t, d):
        l = pos[t] + N; r = n + N
        _push_path(l, r)
        run = 0                     # free times immediately before current position (all >= t)
        stack = []
        ll = l; rr = r
        while ll < rr:
            if ll & 1:
                i = ll
                pf = pref[i]
                if run + pf >= d:           # fit starts at beginning of current free run
                    return L[i] - run
                if best[i] >= d:            # leftmost segment containing a fit -> answer is inside
                    ans, _ = search(i, run, d)
                    return ans
                run = run + pf if pf == length[i] else suff[i]   # skip whole segment, O(1)
                ll += 1
            if rr & 1:
                rr -= 1; stack.append(rr)
            ll >>= 1; rr >>= 1
        while stack:
            i = stack.pop()
            pf = pref[i]
            if run + pf >= d:
                return L[i] - run
            if best[i] >= d:
                ans, _ = search(i, run, d)
                return ans
            run = run + pf if pf == length[i] else suff[i]
        return t                    # unreachable: infinite tail is free

    out = []
    starts = {}                     # booking start -> end
    for op in ops:
        k = op[0]
        if k == "book":
            s = op[1]; e = op[2]
            if s >= e:
                out.append("INVALID")
            elif range_free(pos[s], pos[e]) == e - s:
                range_set(pos[s], pos[e], 0)
                starts[s] = e
                out.append(True)
            else:
                out.append("CONFLICT")
        elif k == "cancel":
            s = op[1]
            e = starts.pop(s, None)
            if e is None:
                out.append(0)
            else:
                range_set(pos[s], pos[e], 1)
                out.append(e - s)
        elif k == "first_fit":
            out.append(first_fit(op[1], op[2]))
        else:                       # free_between
            a = op[1]; b = op[2]
            out.append(0 if a >= b else range_free(pos[a], pos[b]))
    return out

from collections import OrderedDict
from heapq import heappush, heappop
from itertools import count


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, expires_at or None]; oldest use first
    expiry = []            # min-heap of (expires_at, seq, key); may hold stale entries
    seq = count()          # tie-breaker so (possibly unorderable) keys are never compared
    out = []
    last_t = None

    def alive(entry, t):
        # entry written at t0 with ttl expires at t0 + ttl: dead for all T >= t0 + ttl
        return entry[1] is None or t < entry[1]

    def purge(t):
        # Lazily delete every entry whose expiry time has been reached.
        # Heap records that no longer match the stored entry are stale; skip them.
        while expiry and expiry[0][0] <= t:
            exp, _, key = heappop(expiry)
            entry = store.get(key)
            if entry is not None and entry[1] == exp:
                del store[key]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            expires_at = None if ttl is None else t + ttl
            entry = store.get(key)
            if entry is not None:
                if alive(entry, t):
                    # replace value and expiry; the put is a USE, so refresh LRU position
                    entry[0] = value
                    entry[1] = expires_at
                    store.move_to_end(key)
                    if expires_at is not None:
                        heappush(expiry, (expires_at, next(seq), key))
                    continue
                del store[key]  # expired entries occupy no capacity
            if len(store) >= capacity:
                purge(t)  # drop expired entries before considering eviction
                if len(store) >= capacity:
                    store.popitem(last=False)  # evict least recently used unexpired entry
            store[key] = [value, expires_at]
            if expires_at is not None:
                heappush(expiry, (expires_at, next(seq), key))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            elif not alive(entry, t):
                del store[key]
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out
